from pathlib import Path
import re
p = Path('/app/text.gcode')
text = p.read_text(errors='ignore')
lines = text.splitlines()
common = re.compile(r'\b(PrusaSlicer|Slic3r|generated|layer|mm|speed|filament|printer|profile|PLA|PETG|MK4S|gcode|tool|extruder|bed|time|version)\b', re.I)

cands = []
# 1) M117 display text
for line in lines:
    m = re.match(r'^\s*M117\s+(.*)$', line, re.I)
    if m:
        s = m.group(1).strip()
        if s:
            cands.append(s)

# 2) explicit text comments
for line in lines:
    if line.lstrip().startswith(';'):
        s = line.lstrip(';').strip()
        m = re.match(r'(?i)^(?:text|label|caption)\s*[:=]\s*(.+)$', s)
        if m:
            cands.append(m.group(1).strip())
        m = re.search(r'["“](.+?)["”]', s)
        if m:
            cands.append(m.group(1).strip())

# 3) short comment lines that look like the intended printable phrase
for line in lines:
    if line.lstrip().startswith(';'):
        s = line.lstrip(';').strip()
        if 1 <= len(s) <= 60 and re.fullmatch(r'[A-Za-z0-9 .,_-]+', s) and not common.search(s):
            cands.append(s)

# 4) quoted strings anywhere in file
for m in re.finditer(r'["“]([^"”\n]{1,80})["”]', text):
    s = m.group(1).strip()
    if s and not common.search(s):
        cands.append(s)

# choose best candidate
seen = set()
uniq = []
for c in cands:
    c = re.sub(r'\s+', ' ', c).strip()
    if c and c not in seen:
        seen.add(c)
        uniq.append(c)

# prefer a succinct phrase
answer = ''
if uniq:
    # score by brevity and letter content
    def score(s):
        letters = sum(ch.isalpha() for ch in s)
        spaces = s.count(' ')
        return (0 if letters else 10, spaces, len(s))
    answer = sorted(uniq, key=score)[0]

Path('/app/out.txt').write_text(answer)
print(answer)
